responses.text:
{
  "outcome": "revise",
  "issues": [
    {
      "kind": "contradiction",
      "severity": "critical",
      "description": "10행에서 모르는 버전을 읽을 경우 호환을 위해 items를 빈 배열로 바꾸고 version 1로 덮어쓰도록 규정하여, 승인된 기술 제약인 '알 수 없는 스키마 버전은 원본 보존과 쓰기 차단으로 처리한다' 및 R-3 요구사항과 정면으로 모순됩니다.",
      "suggestedDirection": "알 수 없는 스키마 버전이 감지되면 데이터를 덮어쓰거나 초기화하지 않고 원본을 보존하며 쓰기를 차단하도록 기획을 수정하십시오.",
      "relatedRequirementId": "R-3"
    }
  ],
  "suggestions": [
    "10행의 알 수 없는 버전 처리 방식을 '덮어쓰기'에서 '원본 보존 및 쓰기 차단'으로 일치시키십시오."
  ],
  "scopeViolation": true,
  "userJudgmentRequired": false,
  "qualityAssessment": {
    "version": 1,
    "requirements": [
      {
        "requirementId": "R-1",
        "status": "satisfied",
        "evidenceLines": [3, 4, 8],
        "rationale": "물건명/사람명 등록 검증과 동일 물건명에 대한 별개 고유 식별자 부여 규칙이 구체적으로 제시되었습니다."
      },
      {
        "requirementId": "R-2",
        "status": "satisfied",
        "evidenceLines": [5, 9],
        "rationale": "선택한 대상 한 건의 반환 상태 전이 및 타 항목 불변, 반복 반환 요청에 대한 멱등성이 명시되었습니다."
      },
      {
        "requirementId": "R-3",
        "status": "missing",
        "evidenceLines": [6, 10],
        "rationale": "10행에서 모르는 버전 데이터를 빈 배열로 덮어쓰도록 규정하여 원본 데이터 보존 및 쓰기 차단 요구사항과 충돌합니다."
      }
    ],
    "checks": [
      {
        "id": "decision_provenance",
        "status": "satisfied",
        "evidenceLines": [12],
        "rationale": "사용자 결정 출처와 기획자의 위임된 설계 제안 구분이 명확하게 유지되고 있습니다."
      },
      {
        "id": "scope_compliance",
        "status": "missing",
        "evidenceLines": [10, 13],
        "rationale": "제외 기능은 준수했으나 승인된 기술 제약인 알 수 없는 버전 원본 보존 및 쓰기 차단을 위반했습니다."
      },
      {
        "id": "behavior_and_errors",
        "status": "missing",
        "evidenceLines": [3, 10],
        "rationale": "비정상/알 수 없는 스키마 버전 처리 동작이 승인된 오류 처리 제약과 상충합니다."
      },
      {
        "id": "data_integrity",
        "status": "missing",
        "evidenceLines": [10],
        "rationale": "알 수 없는 버전 감지 시 기존 데이터를 빈 배열로 덮어써 영속 데이터 손실이 유발됩니다."
      },
      {
        "id": "acceptance_criteria",
        "status": "satisfied",
        "evidenceLines": [8, 9, 10],
        "rationale": "등록, 상태 변경, 저장 및 실패 시나리오에 대한 관찰 가능한 기준이 명확합니다."
      },
      {
        "id": "revision_resolution",
        "status": "not_applicable",
        "evidenceLines": [13],
        "rationale": "초기 기획안으로 settledDecisions에 해결해야 할 이전 수정 요청이 없습니다."
      },
      {
        "id": "clarity",
        "status": "satisfied",
        "evidenceLines": [2, 3, 4, 5, 6, 7],
        "rationale": "사용자 시나리오 예시를 선행 배치하고 구현 세부 사항을 분리하여 명확하게 서술했습니다."
      }
    ]
  }
}
